#!/usr/bin/env node
/**
 * pnpm harness — keep each harness's config in step with one manifest.
 *
 *   pnpm harness sync    write the generated files (Codex, DSH) from
 *                        utils/harness/hooks.js; never touches .claude/
 *   pnpm harness check   fail when a generated file is stale, or when
 *                        .claude/settings.json hooks differ from the manifest
 *
 * `.claude/settings.json` is hand-written (Claude Code is first-class), so
 * sync only reports a difference there. Generated files are compared by
 * content (JSON by value), so reformatting one is not a change.
 */
import fs from 'fs';
import path from 'path';
import { runIfMain } from '../module-runner.js';
import { ROOT_DIR } from '../workspace-config.js';
import {
  HOOKS,
  diffEntries,
  hookEntries,
  readHookEntries,
  renderHooksConfig,
} from './hooks.js';
import { readPermissions, renderCodexRules } from './permissions.js';
import { codexRoleFiles } from './roles.js';
import { DSH_BRIDGE_INSTALL, DSH_PATCH } from '../loop/adapters.js';

const MANIFEST = 'utils/harness/hooks.js';
const CLAUDE_SETTINGS = '.claude/settings.json';
/**
 * The DSH overlay that runs the workspace's hooks through DSH's Claude hooks
 * bridge. DSH has no project config, so it is passed on launch
 * (`dsh <profile> --patch …`; pnpm loop/swarm/agent ask do it).
 *
 * `projectDir` makes the bridge write the path into each command when it
 * reads `.dsh/hooks.json` (see hookCommand): DSH runs hooks with pwsh on
 * Windows, which does not read the env var. `process.cwd()` is the launch
 * dir, which `configPath` is relative to as well; `.` would make
 * `CLAUDE_PROJECT_DIR` relative. The braced commands and `!!js process.cwd()`
 * ran with `dsh web` 0.2.2-rc.3 on Windows: SessionStart, UserPromptSubmit,
 * PreToolUse, PostToolUse, and Stop exited 0.
 */
const DSH_PATCH_CONTENT = `# Generated by pnpm harness sync; do not edit.
# Runs this workspace's hooks (.dsh/hooks.json) through DSH's Claude hooks bridge.
# Start DSH at the workspace root: dsh <profile> --patch ${DSH_PATCH}
# Install the bridge and its two peers into each profile you start (headless for
# pnpm agent ask/loop/swarm, web, tui), at the version dsh --version prints:
#   ${DSH_BRIDGE_INSTALL}
- insert:
    - id: hooks-claude-code
      name: '@deepseek-ai/dsh-hooks-claude-code'
      config:
        configPath: ./.dsh/hooks.json
        projectDir: !!js process.cwd()
`;
const CODEX_HOOKS_DESCRIPTION =
  'Generated by pnpm harness sync from utils/harness/hooks.js; do not edit. Codex runs a changed hook only after you trust it with /hooks.';

/**
 * @typedef {{ rootDir: string, log: (line: string) => void }} Deps
 * @typedef {{ file: string, content: string, json?: boolean, changedHint?: { text: string, when: (previous: string | null) => boolean } }} GeneratedFile
 *   changedHint: printed after sync rewrote the file, when `when` says the
 *   change matters (given the previous content, null for a new file)
 */

/**
 * Whether a Codex hooks file's hook entries differ from the manifest's: only
 * then must the user trust them again (the description does not count).
 *
 * @param {string | null} previous
 */
function codexHooksChanged(previous) {
  try {
    const { missing, extra } = diffEntries(
      hookEntries('codex'),
      readHookEntries(JSON.parse(String(previous)))
    );
    return missing.length > 0 || extra.length > 0;
  } catch {
    return true;
  }
}

/**
 * Every file `pnpm harness sync` writes, with its content.
 *
 * @param {{ specs?: import('./hooks.js').HookSpec[], rootDir?: string }} [options]
 * @returns {GeneratedFile[]}
 */
export function generatedFiles({ specs = HOOKS, rootDir = ROOT_DIR } = {}) {
  /** @type {GeneratedFile[]} */
  const files = [];
  const codex = renderHooksConfig('codex', {
    specs,
    description: CODEX_HOOKS_DESCRIPTION,
  });
  if (codex) {
    files.push({
      file: '.codex/hooks.json',
      content: `${JSON.stringify(codex, null, 2)}\n`,
      json: true,
      changedHint: {
        text: 'Codex: run /hooks in Codex here to trust the changed hooks (each one is skipped until trusted).',
        when: codexHooksChanged,
      },
    });
  }
  const dsh = renderHooksConfig('dsh', { specs });
  if (dsh) {
    files.push(
      {
        file: '.dsh/hooks.json',
        content: `${JSON.stringify(dsh, null, 2)}\n`,
        json: true,
      },
      { file: DSH_PATCH, content: DSH_PATCH_CONTENT }
    );
  }
  files.push(...codexRoleFiles(rootDir));
  const settings = readSettings(rootDir);
  if (settings) {
    files.push({
      file: '.codex/rules/workspace.rules',
      content: renderCodexRules(readPermissions(settings)),
      changedHint: {
        text: 'Codex: the command rules apply from the next Codex session.',
        when: () => true,
      },
    });
  }
  return files;
}

/**
 * @param {string} rootDir
 * @returns {unknown} the parsed .claude/settings.json, or null
 */
function readSettings(rootDir) {
  try {
    return JSON.parse(
      fs.readFileSync(path.join(rootDir, CLAUDE_SETTINGS), 'utf-8')
    );
  } catch {
    return null;
  }
}

/**
 * Whether a generated file on disk already has its content.
 *
 * @param {string} rootDir
 * @param {GeneratedFile} generated
 * @returns {'current' | 'stale' | 'missing'}
 */
function fileState(rootDir, generated) {
  const file = path.join(rootDir, generated.file);
  if (!fs.existsSync(file)) return 'missing';
  const actual = fs.readFileSync(file, 'utf-8');
  if (!generated.json)
    return actual === generated.content ? 'current' : 'stale';
  try {
    return JSON.stringify(JSON.parse(actual)) ===
      JSON.stringify(JSON.parse(generated.content))
      ? 'current'
      : 'stale';
  } catch {
    return 'stale';
  }
}

/** @param {import('./hooks.js').HookEntry} entry */
const describeEntry = (entry) =>
  `${entry.event}${entry.matcher === null ? '' : ` [${entry.matcher}]`}: ${entry.command}${entry.timeout === null ? '' : ` (timeout ${entry.timeout})`}`;

/**
 * Compare `.claude/settings.json` hooks with the manifest.
 *
 * @param {Deps} deps
 * @returns {boolean} true when they match
 */
function checkClaude({ rootDir, log }) {
  let settings;
  try {
    settings = JSON.parse(
      fs.readFileSync(path.join(rootDir, CLAUDE_SETTINGS), 'utf-8')
    );
  } catch (error) {
    log(
      `✗ ${CLAUDE_SETTINGS} cannot be read: ${/** @type {Error} */ (error).message}`
    );
    return false;
  }
  const { missing, extra } = diffEntries(
    hookEntries('claude'),
    readHookEntries(settings)
  );
  if (missing.length === 0 && extra.length === 0) {
    log(`✓ ${CLAUDE_SETTINGS} hooks match ${MANIFEST}`);
    return true;
  }
  log(`✗ ${CLAUDE_SETTINGS} hooks differ from ${MANIFEST}:`);
  for (const entry of missing) log(`  missing: ${describeEntry(entry)}`);
  for (const entry of extra) log(`  extra: ${describeEntry(entry)}`);
  log(
    `Fix: make ${CLAUDE_SETTINGS} hooks and ${MANIFEST} agree, then pnpm harness sync`
  );
  return false;
}

const COMMANDS = {
  /** @param {Deps} deps */
  sync(deps) {
    const written = [];
    for (const generated of generatedFiles({ rootDir: deps.rootDir })) {
      const state = fileState(deps.rootDir, generated);
      if (state === 'current') continue;
      const file = path.join(deps.rootDir, generated.file);
      const previous =
        state === 'missing' ? null : fs.readFileSync(file, 'utf-8');
      fs.mkdirSync(path.dirname(file), { recursive: true });
      fs.writeFileSync(file, generated.content);
      deps.log(`Wrote ${generated.file}`);
      if (generated.changedHint?.when(previous)) {
        deps.log(generated.changedHint.text);
      }
      written.push(generated.file);
    }
    if (written.length === 0) deps.log('✓ generated files are up to date');
    // sync never edits Claude's settings; it reports a difference instead.
    return checkClaudeQuietly(deps) ? 0 : 1;
  },

  /** @param {Deps} deps */
  check(deps) {
    let ok = checkClaude(deps);
    for (const generated of generatedFiles({ rootDir: deps.rootDir })) {
      const state = fileState(deps.rootDir, generated);
      if (state === 'current') {
        deps.log(`✓ ${generated.file}`);
        continue;
      }
      ok = false;
      deps.log(
        `✗ ${generated.file} is ${state === 'missing' ? 'missing' : 'out of date'}`
      );
      deps.log('Fix: pnpm harness sync');
    }
    return ok ? 0 : 1;
  },

  /** @param {Deps} deps */
  help(deps) {
    deps.log(
      [
        'Usage:',
        `  pnpm harness sync    write the Codex/DSH files generated from ${MANIFEST}`,
        `  pnpm harness check   fail when a generated file or ${CLAUDE_SETTINGS} hooks differ from it`,
      ].join('\n')
    );
    return 0;
  },
};

/**
 * The Claude comparison for sync: silent when it matches.
 *
 * @param {Deps} deps
 */
function checkClaudeQuietly(deps) {
  /** @type {string[]} */
  const lines = [];
  const ok = checkClaude({ ...deps, log: (line) => lines.push(line) });
  if (!ok) lines.forEach((line) => deps.log(line));
  return ok;
}

/**
 * @param {{ argv?: string[], deps?: Partial<Deps> }} [options]
 * @returns {number}
 */
export function main({ argv = process.argv.slice(2), deps = {} } = {}) {
  /** @type {Deps} */
  const resolved = {
    rootDir: ROOT_DIR,
    log: (line) => console.log(line),
    ...deps,
  };
  const command = argv[0] ?? 'help';
  if (!Object.hasOwn(COMMANDS, command)) {
    throw new Error(`Unknown command "${command}". Run: pnpm harness help`);
  }
  return COMMANDS[/** @type {keyof typeof COMMANDS} */ (command)](resolved);
}

/* c8 ignore next 8 - CLI entry point */
runIfMain(import.meta.url, () => {
  try {
    process.exit(main());
  } catch (error) {
    console.error('Error:', error instanceof Error ? error.message : error);
    process.exit(1);
  }
});
